def try_pair(I,O):
    H,W=len(I),len(I[0])
    cs=[(c,s) for c,s in comps(I) if c not in (2,5)]
    outs=[(c,s) for c,s in comps(O)]
    res=[]
    for p1 in cs:
        c1,s1=p1
        for dr1 in range(-H,H+1):
            for dc1 in range(-W,W+1):
                s1t={(a+dr1,b+dc1) for a,b in s1}
                if not all(0<=a<H and 0<=b<W for a,b in s1t): continue
                for p2 in cs:
                    if p2 is p1: continue
                    c2,s2=p2
                    for dr2 in range(-H,H+1):
                        for dc2 in range(-W,W+1):
                            s2t={(a+dr2,b+dc2) for a,b in s2}
                            if not all(0<=a<H and 0<=b<W for a,b in s2t): continue
                            if s1t & s2t: continue
                            u=s1t|s2t
                            exp=[[O[r][j] for j in range(W)] for r in range(H)]
                            good=True
                            for a,b in u:
                                # color from p1 or p2
                                col = c1 if (a-dr1,b-dc1) in s1 else c2
                                if O[a][b]!=col: good=False;break
                                if len(exp)<max(a)+1: break
                            if good and sorted(u)==sorted((a,b) for a,b in [(x,y) for x,y in [] ] ): 
                                pass
    return None

