def components(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=5 and not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cs=[]
                while q:
                    a,b=q.popleft(); cs.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
