                            if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==c:
                                seen[x][y]=True; q.append((x,y))
                r0=min(a for a,b in cs); r1=max(a for a,b in cs)
                c0=min(b for a,b in cs); c1=max(b for a,b in cs)
                comps.append({'c':c,'cells':cs,'r0':r0,'r1':r1,'c0':c0,'c1':c1})
    return comps

def f(inp):
    H,W=len(inp),len(inp[0])
    comps=components(inp)
    kept=None; cands=[]
    for comp in comps:
        if comp['c']==1 and comp['r0']>5:
            # candidate kept if no column conflict with other non-2 pieces
            others=[p for p in comps if p['c']!=2 and p is not comp]
            bad=[o for o in others if set(range(o['c0'],o['c1']+1)) & set(range(comp['c0'],comp['c1']+1))]
            if not bad: kept=comp
    if kept is None:
        # fallback: any 1-piece below divider with no column conflict
        for comp in comps:
            if comp['c']==1 and comp['r0']>5:
                others=[p for p in comps if p['c']!=2 and p is not comp]
                bad=[o for o in others if set(range(o['c0'],o['c1']+1))&set(range(comp['c0'],comp['c1']+1))]
                if not bad: kept=comp; break
    kc=kept['c']; kcells=kept['cells']; kr0=kept['r0']; kc0=kept['c0']; kc1=kept['c1']
    out=[[0]*W for _ in range(H)]
    for a,b in kcells: out[a-6][b]=1
    others=[p for p in comps if p['c']!=2 and p is not kept]
    def dist(p):
        return max(abs(p['c0']-kc0), abs(p['c1']-kc1))
    best=max(others,key=dist)
    oc=best['c']; bcells=best['cells']; br0=best['r0']; bc0=best['c0']
    base=kr0-7 if br0<kr0 else kr0-5
    # place flush adjacent vertically
    if base>=0 and sum(1 for r in range(base,base+len(best['cells']))):
        pass
    # determine placement side: above if piece above kept originally, else below
    above = br1 < kr0
    if above and base>=0:
        cur=base
        for r,c in sorted(bcells): out[cur+r-br0][kc0+(c-bc0)]=oc; cur-=1
    else:
        cur=kr0-5  # row just below kept's top after shift
        for r,c in sorted(bcells): out[cur+r-br0][kc0+(c-bc0)]=oc; cur+=1
    return out

