    b=[x for x in pieces if min(r for r,_ in x[1])>d]; a=[x for x in pieces if min(r for r,_ in x[1])<d]
    dup=max(b,key=len)
    # collapse duplicates: keep dup if its shape occurs elsewhere above; otherwise keep dup
    def norm(cells):
        r0=min(r for r,_ in cells); c0=min(c for _,c in cells)
        return tuple(tuple('#' if (r,c) in set(cells) else '.' for c in range(max(c for _,c in cells)-c0+1)) for r in range(max(r for r,_ in cells)-r0+1))
    ds=norm(dup[1]); dset={ds}
    others=[]
    for x in a:
        ns=norm(x[1])
        if ns not in dset: others.append(x)
    # rightmost unique
    if others: oth=max(others,key=lambda x:max(c for _,c in x[1]))
    else: oth=None
    O=[[0]*w for _ in range(9)]
    for r,c in dup[1]: O[r-6][c]=dup[0]
    if oth:
        oh=max(r for r,_ in oth[1])-min(r for r,_ in oth[1])+1
        ow=max(c for _,c in oth[1])-min(c for _,c in oth[1])+1
        dw=max(c for _,c in dup[1])-min(c for _,c in dup[1])+1
        # slide horizontally to align column spans (use dup's span)
        dc=min(c for _,c in dup[1])
        # target column offset so other's left = dup's left
        ocells=[(r,min(c for _,c in oth[1])+dc-min(c for _,c in oth[1]),v) for r,c,v in oth[1]]
        for r,c in ocells: O[r][c]=oth[0]
        # vertical: flush above or below, no overlap, min movement
        drows={(rt-6,cc) for rt,cc in dup[1]}
        for side,top in ((dt_ -oh,),(dt_+1,)):
            pass
        best=None
        for top in (min(r for r,_ in dup[1])-oh, max(r for r,_ in dup[1])+1):
            if not all(0<=top+r<9 for r in range(oh)): continue
            cells={(top+r, min(c for _,c in oth[1])+dc-min(c for _,c in oth[1])) for r,c in oth[1]}
            if cells & drows: continue
            move=abs(top-min(r for r,_ in oth[1]))
            if best is None or move<best[0]: best=(move,top)
        _,top=best
        for r,c in ocells: O[top+r][c]=oth[0]
